async function fetchAll(urls) {
  const results = await Promise.all(
    urls.map((u) => fetch(u).then((r) => r.json()))
  );
  return results.filter(Boolean);
}

impl Iterator for Counter {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.count < 5 {
            self.count += 1;
            Some(self.count)
        } else {
            None
        }
    }
}

def query_prefix(model: str) -> str | None:
    if "f2llm-v2" in model:
        return ("Instruct: Given a question, retrieve passages "
                "that can help answer the question.\nQuery: ")
    if "arctic-embed" in model and "-v2" in model:
        return "query: "
    return None

type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

const unwrap = <T,>(r: Result<T>): T => {
  if (!r.ok) throw new Error(r.error);
  return r.value;
};

// Kommentar auf Deutsch: berechnet den gleitenden Mittelwert
float moving_average(const float * x, int n, int w) {
    float s = 0.0f;
    for (int i = n - w; i < n; ++i) s += x[i];
    return s / (float) w;
}
